package com.openggf.game.soniccd;
import com.openggf.game.soniccd.level.*;
import com.openggf.game.soniccd.objects.*;
import com.openggf.game.soniccd.player.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static com.openggf.game.soniccd.objects.CdObjectState.ByteField.*;
import static com.openggf.game.soniccd.objects.CdObjectState.WordField.*;
import static com.openggf.game.soniccd.objects.CdObjectState.LongField.*;
import static org.junit.jupiter.api.Assertions.*;
/** Actual original source plus explicitly constructed component/pool/scalar fault controls.
 * These values are never public engine ingress or native captures. All Java UNRUN. */
class TestCdOriginalR11LostRingComponents {
 @Test void constructedPlacementCannotBorrowTheOriginalSourceFactory()throws Exception{var a=TestCdOriginalBootPrefix.source().assets();var p=new CdObjectPlacementRuntime(a.placements());assertThrows(IllegalArgumentException.class,()->CdLostRing.fromOriginalPresentAssets(p,a,null,null,null,null,null,null,null));}
 @Test void genuineOriginalFactoryReusesTheExistingRingMapAndTileOwner()throws Exception{var h=new H();var expected=h.a.openingObjects().rings();var actual=h.body.assets().rings();assertArrayEquals(expected.mappings().copy(),actual.mappings().copy());assertArrayEquals(expected.animationTable().copy(),actual.animationTable().copy());assertEquals(expected.mappingTableOffset(),actual.mappingTableOffset());assertEquals(expected.mappingFrames().size(),actual.mappingFrames().size());assertEquals(expected.animations().size(),actual.animations().size());assertEquals(0x20A0FA,h.body.assets().mappingsAddress());assertEquals(0xA7AE,h.body.assets().baseTileWord());assertFalse(h.body.isCurrentInvocation(35,h.inputs,h.ports));}
 @Test void initAllocatesRealFirstFreeSlotsAndPreservesDirtyFractionsBeforeOneFm()throws Exception{var h=new H();h.p.pool().write(h.p.pool().state(32).moveWord(X_FRACTION,0x1234).moveWord(Y_FRACTION,0x5678));h.rings=new CdRingGlobals(2,3,0x80,7,8,9,10,2);var saved=h.p.capture().savedFlags();var r=h.run();assertEquals(2,r.effects().stream().filter(CdLostRing.RingInitialized.class::isInstance).count());assertEquals(0x1234,h.p.pool().state(32).word(X_FRACTION));assertEquals(0x5678,h.p.pool().state(32).word(Y_FRACTION));assertEquals(0,h.rings.rings());assertEquals(0,h.rings.livesFlags());assertEquals(0x80,h.rings.updateHudRings());assertEquals(0xFF,h.spill.timerByte());assertEquals(0x4567,h.spill.accumWord());assertEquals(1,h.sounds.size());assertEquals(1,h.draws);assertArrayEquals(saved.copy(),h.p.capture().savedFlags().copy());}
 @Test void fullPoolRetainsSelfInitAndStopsAllocationWithoutOverwritingOthers()throws Exception{var h=new H();for(int w=32;w<128;w++)if(w!=35)h.p.pool().write(h.p.pool().state(w).moveByte(ID,0x7F).moveWord(X_FRACTION,w));h.rings=new CdRingGlobals(16,3,0,0,0,0,0,0);var before=h.p.capture();var r=h.run();assertTrue(r.effects().stream().anyMatch(CdLostRing.SlotUnavailable.class::isInstance));for(var old:before.pool().slots())if(old.identity().wholeIndex()!=35)assertArrayEquals(old.copyBytes(),h.p.pool().state(old.identity().wholeIndex()).copyBytes());assertEquals(0,h.rings.rings());assertEquals(1,h.sounds.size());}
 @Test void fmFailureRetainsCompletedInitAndGlobalPrefixWithoutMainOrDraw()throws Exception{var h=new H();var failure=new IllegalStateException("source FM refusal");h.fmFailure=failure;assertSame(failure,assertThrows(IllegalStateException.class,h::run));assertEquals(2,h.slot().routine());assertEquals(0,h.rings.rings());assertEquals(0xFF,h.spill.timerByte());assertEquals(0,h.draws);assertFalse(h.body.isCurrentInvocation(35,h.inputs,h.ports));}
 @Test void collectUsesOneExistingRewardOwnerThenActualPrefixAnimatorAndDraw()throws Exception{var h=new H();h.p.pool().write(h.slot().moveByte(ROUTINE,4).moveByte(ANIMATION,0).moveByte(PREVIOUS_ANIMATION,0).moveByte(ANIMATION_TIME,5).moveByte(ANIMATION_FRAME,0));h.rings=new CdRingGlobals(99,3,0,0,0,0,7,2);h.run();assertEquals(100,h.rings.rings());assertEquals(4,h.rings.lives());assertEquals(1,h.collects);assertEquals(1,h.sounds.size());assertInstanceOf(CdLostRing.RewardSubCpuRequest.class,h.sounds.getFirst().request());assertEquals(1,h.draws);}
 @Test void originalSparkleDirectoryFaultRetainsTheSharedKernelResetPrefix()throws Exception{var h=new H();h.p.pool().write(h.slot().moveByte(ROUTINE,6).moveByte(ANIMATION,0).moveByte(PREVIOUS_ANIMATION,1).moveByte(ANIMATION_TIME,99).moveByte(ANIMATION_FRAME,88));var failure=new IllegalStateException("animation selected read refusal");h.animationFailure=failure;assertSame(failure,assertThrows(IllegalStateException.class,h::run));assertEquals(0,h.slot().unsignedByte(PREVIOUS_ANIMATION));assertEquals(255,h.slot().unsignedByte(ANIMATION_TIME));assertEquals(0,h.slot().unsignedByte(ANIMATION_FRAME));assertEquals(0,h.draws);assertFalse(h.body.isCurrentAnimationCall(h.lastAnimation));}
 @Test void timerDeletionAndWrongPhysicalD7RetainTheExactSharedBoundaries()throws Exception{var h=new H();h.p.pool().write(h.slot().moveByte(ROUTINE,2).moveWord(Y_VELOCITY,-0x100));h.inputs=new CdLostRing.Inputs(0,91,0,0x1000);var before=h.p.capture();assertThrows(IllegalArgumentException.class,h::run);assertEquals(before.pool().slots(),h.p.capture().pool().slots());h.inputs=new CdLostRing.Inputs(0,92,0,0x1000);h.spill=new CdRingSpillGlobals(0,0x4567,2);h.run();assertArrayEquals(new byte[64],h.slot().copyBytes());assertEquals(0,h.draws);}
 private static final class H {
  final CdR11aAssets a;final CdObjectPlacementRuntime p;CdLostRing body;CdRingGlobals rings=new CdRingGlobals(1,3,0,0,0,0,7,2);CdRingSpillGlobals spill=new CdRingSpillGlobals(9,0x4567,2);CdLostRing.Inputs inputs=new CdLostRing.Inputs(0,92,0,0x1000);final CdLostRing.Ports ports;int draws,collects;RuntimeException fmFailure,animationFailure;CdObjectAnimation.Operation lastAnimation;final List<CdLostRing.SoundCall> sounds=new ArrayList<>();
  H()throws Exception{a=TestCdOriginalBootPrefix.source().assets();p=CdObjectPlacementRuntime.fromAssets(a);p.pool().write(p.pool().state(35).moveByte(ID,0x11).moveWord(X,0x200).moveWord(Y,0x700));ports=new CdLostRing.Ports(new CdRing.GlobalsPort(){public CdRingGlobals read(){return rings;}public void write(CdRingGlobals next){assertTrue(body.isCurrentCall(next));rings=next;}},new CdLostRing.SpillGlobalsPort(){public CdRingSpillGlobals read(){return spill;}public void write(CdRingSpillGlobals next){assertTrue(body.isCurrentCall(next));spill=next;}});
   body=CdLostRing.fromOriginalPresentAssets(p,a,new CdPlayerMath(a.player()),new CdPlayerTerrain(a.terrain()),c->{assertTrue(body.isCurrentCall(c));},c->{assertTrue(body.isCurrentCall(c));assertSame(c.cut(),body.currentSource(c));sounds.add(c);if(fmFailure!=null)throw fmFailure;},(pool,id)->{assertTrue(body.isCurrentDrawCall(pool,id));assertThrows(IllegalStateException.class,this::run);draws++;var row=pool.state(id.wholeIndex());pool.write(row.moveByte(SPRITE_FLAGS,row.spriteFlags()&127));},(g,c)->{assertTrue(body.isCurrentCollectCall(g,c));collects++;CdLostRing.collectRing(g,c);},new CdObjectAnimation.Guard(){public void before(CdObjectAnimation.Operation c){assertTrue(body.isCurrentAnimationCall(c));lastAnimation=c;if(c.kind()==CdObjectAnimation.Kind.DIRECTORY&&animationFailure!=null)throw animationFailure;}public void after(CdObjectAnimation.Operation c){assertTrue(body.isCurrentAnimationCall(c));}});
  }
  CdObjectState slot(){return p.pool().state(35);}CdLostRing.Result run(){return body.run(35,inputs,ports);}
 }
}
